using Microsoft.EntityFrameworkCore;
using Shuffull.Core.Models.Enums;
using System.ComponentModel.DataAnnotations;

namespace Shuffull.Core.Models.Database;

/// <summary>
/// One play of one song by one user: the listen log the skip stats and the December recap read
/// (shuffull-workspace#35). Written by the app's outbox through <c>POST /api/v1/listens</c>.
///
/// <para><see cref="ListenId"/> is generated by the app, so a resend of the same listen hits the key and records
/// nothing new.</para>
///
/// <para>A listen is history, so it outlives its song. <see cref="SongId"/> and <see cref="PlaylistId"/> are plain
/// columns with no foreign key: a purged audition song (<c>DeletePlaylistHandler</c>) or a deleted playlist leaves
/// its listens in place, and the recap still counts the time. A replaced song keeps its <c>SongId</c>, so its
/// listens stay attached to it.</para>
/// </summary>
[Index(nameof(UserId), nameof(StartedAt))]
[Index(nameof(UserId), nameof(SongId), nameof(StartedAt))]
public class Listen
{
    public const int MaxIdLength = 64;
    public const int MaxPlatformLength = 32;

    [Key, MaxLength(MaxIdLength)]
    public string ListenId { get; set; }

    [Required]
    public string UserId { get; set; }

    [Required, MaxLength(MaxIdLength)]
    public string SongId { get; set; }

    [Required]
    public DateTime StartedAt { get; set; }

    [Required]
    public DateTime EndedAt { get; set; }

    /// <summary>Time the song actually played: pauses, buffering and seeks don't count. So it is at most
    /// <see cref="EndedAt"/> minus <see cref="StartedAt"/>, and less after a pause.</summary>
    [Required]
    public double SecondsListened { get; set; }

    /// <summary>The song's length as the app knew it, for completion %. Null if the app didn't know it.</summary>
    public double? SongDurationSeconds { get; set; }

    [Required]
    public ListenEndReason EndReason { get; set; }

    [Required]
    public ListenContext Context { get; set; }

    /// <summary>The playlist it was played from, if any.</summary>
    [MaxLength(MaxIdLength)]
    public string? PlaylistId { get; set; }

    /// <summary>The app's platform as it reports it (android, ios, web, desktop). Free text, so a new platform's
    /// listens aren't refused.</summary>
    [MaxLength(MaxPlatformLength)]
    public string? Platform { get; set; }

    /// <summary>When the server stored it. A listen made offline arrives later than it happened.</summary>
    [Required]
    public DateTime RecordedAt { get; set; }

    public User User { get; set; }
}
